package ca.yorku.eecs3311.coursepilot.domain.model;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="study_plans") public class StudyPlan { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="course_id") Course course; @Column(nullable=false) LocalDate startDate; @Column(nullable=false) LocalDate targetDate; @Column(nullable=false) int availableMinutes; @Column(nullable=false,length=40) String strategy; @Column(nullable=false) Instant createdAt; @OneToMany(mappedBy="plan",cascade=CascadeType.ALL,orphanRemoval=true) @OrderBy("scheduledDate asc, sequenceNumber asc") List<StudyPlanItem> items=new ArrayList<>(); protected StudyPlan(){} public StudyPlan(Course c,LocalDate start,LocalDate target,int minutes,String strategy){course=c;startDate=start;targetDate=target;availableMinutes=minutes;this.strategy=strategy;} @PrePersist void create(){createdAt=Instant.now();} public Long getId(){return id;} public Course getCourse(){return course;} public LocalDate getStartDate(){return startDate;} public LocalDate getTargetDate(){return targetDate;} public int getAvailableMinutes(){return availableMinutes;} public String getStrategy(){return strategy;} public Instant getCreatedAt(){return createdAt;} public List<StudyPlanItem> getItems(){return items;} public void addItem(StudyPlanItem item){items.add(item);} }
